def build_travel_card(idx: int) -> str:
    """Return SVG markup for the hotel/sanctuary card at idx (0..14)."""
    if not (0 <= idx < len(CARDS)):
        raise IndexError(f"Card index {idx} out of range (0..{len(CARDS)-1})")
    return CARDS[idx]


def main() -> None:
    cards = [build_travel_card(i) for i in range(15)]
    for lang in ("en", "hu"):
        path = ROOT / lang / "travel-guide.html"
        update_page_cards(path, "hotel-art", cards)


if __name__ == "__main__":
    main()
